class Solution:
    def maxPotholes(self, road: str, budget: int) -> int:
        lens = sorted((len(s) for s in road.split('.') if s), reverse=True)
        ans = 0
        for L in lens:
            if budget < 2:
                break
            take = min(L, budget - 1)
            ans += take
            budget -= take + 1
        return ans

