        for (char c : road) {
            if (c == 'x') cur++;
            else { if (cur) lens.push_back(cur); cur = 0; }
        }
        if (cur) lens.push_back(cur);
        sort(lens.rbegin(), lens.rend());
        int ans = 0;
        for (int L : lens) {
            if (budget < 2) break;
            int take = min(L, budget - 1);
            ans += take;
            budget -= take + 1;
        }
        return ans;
    }
};

