class Solution {
public:
    int maxPotholes(string road, int budget) {
        int n = road.size();
        vector<int> cnt(n + 1, 0);
        int cur = 0;
        for (char c : road) {
            if (c == 'x') cur++;
            else { if (cur) cnt[cur]++; cur = 0; }
        }
        if (cur) cnt[cur]++;
        int ans = 0;
        for (int L = n; L >= 1; L--) {
            for (int i = 0; i < cnt[L]; i++) {
                if (budget < 2) return ans;
                int take = min(L, budget - 1);
                ans += take;
                budget -= take + 1;
            }
        }
        return ans;
    }
};

